def fallback_rate(p_syn0, fix_syn, p_str, fix_str, R):
    p_syn, p_struct = p_syn0, p_str          # 当前「仍失败」的概率
    for _ in range(R):
        p_syn *= (1 - fix_syn)
        p_struct *= (1 - fix_str)
    return p_syn + (1 - p_syn) * p_struct    # 语法失败 + 语法成功后的结构失败

for R in range(4):
    print(R, round(fallback_rate(0.30, 0.60, 0.20, 0.50, R), 4))

def stops(acc, cost_ex=150, base=400, price=2e-6, val=0.5):
    ks = sorted(acc)
    rows = []
    for a, b in zip(ks, ks[1:]):
        d_pp = acc[b] - acc[a]
        d_tok = (b - a) * cost_ex
        cost = d_tok * price * 1000          # 元/千次
        rows.append((a, b, d_pp, cost / d_pp, d_pp * val - cost))
    return rows

acc = {0: 61.0, 1: 72.5, 2: 78.0, 4: 83.5, 8: 86.0, 16: 87.5}
for a, b, pp, cpp, net in stops(acc):
