    print(f"{a}->{b}: 边际 {pp:.1f}pp, {cpp:.2f} 元/pp/千次, 净 {net:+.2f} {flag}")

def c_star(acc_d, acc_c, cost_d, cost_c):
    d = acc_c - acc_d
    if d <= 0:
        return float("inf")          # 无增益或反噬：禁用
    return (cost_c - cost_d) / (cost_d * d)

